* { box-sizing: border-box; }
:root { color-scheme: light; font-family: system-ui, sans-serif; font-size: 16px; background: #edf2ef; color: #18332e; }
body { min-height: 100vh; margin: 0; padding: 32px 16px; display: grid; place-items: center; background: radial-gradient(circle at 15% 10%, #d4e6dc, transparent 36%), #edf2ef; }
.booking-card { width: min(100%, 460px); padding: 32px; border: 1px solid #d5e1da; border-radius: 24px; background: #fff; box-shadow: 0 18px 50px #18332e18; }
.eyebrow { margin: 0 0 10px; color: #43846e; font-size: .8rem; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 0; font-size: clamp(1.8rem, 8vw, 2.4rem); line-height: 1.1; }
.intro { margin: 10px 0 24px; color: #60736d; }
.bus { padding: 20px 18px 16px; border: 1px solid #dce7e1; border-radius: 20px; background: #f7faf8; }
.driver-row { display: flex; justify-content: space-between; align-items: center; margin: 0 5px 14px; color: #71827c; font-size: .75rem; font-weight: 700; letter-spacing: .1em; }
.wheel { width: 32px; height: 32px; display: grid; place-items: center; border: 2px solid #bed0c7; border-radius: 50%; color: #43846e; font-size: 1.1rem; }
.seat-map { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)) 22px repeat(2, minmax(0, 1fr)); gap: 9px 7px; }
.seat { min-height: 42px; border: 2px solid #b9d3c6; border-radius: 10px 10px 6px 6px; background: #e5f2ea; color: #255c48; font: inherit; font-weight: 750; cursor: pointer; transition: transform .12s, background .12s, box-shadow .12s; }
.seat:hover:not(:disabled) { transform: translateY(-2px); background: #d4ebdd; }
.seat:active:not(:disabled) { transform: translateY(1px); }
.seat:focus-visible { outline: 3px solid #e59c48; outline-offset: 3px; }
.seat.selected { border-color: #246b53; background: #246b53; color: white; box-shadow: inset 0 -3px #174d3b; }
.seat.booked { border-color: #d4dcd8; background: #e7eae8; color: #87938e; cursor: not-allowed; text-decoration: line-through; }
.aisle { grid-column: 3; grid-row: 1 / span 10; display: grid; place-items: center; color: #afbeb7; font-size: .65rem; letter-spacing: .12em; writing-mode: vertical-rl; }
.legend { display: flex; justify-content: center; flex-wrap: wrap; gap: 14px; margin-top: 18px; color: #60736d; font-size: .83rem; }
.legend span { display: inline-flex; align-items: center; gap: 6px; }
.swatch { width: 13px; height: 13px; border: 1px solid #b9d3c6; border-radius: 4px; background: #e5f2ea; }
.swatch.selected { border-color: #246b53; background: #246b53; }
.swatch.booked { border-color: #d4dcd8; background: #e7eae8; }
.summary { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-top: 24px; padding: 17px 18px; border-radius: 14px; background: #f1f7f3; }
h2 { margin: 0 0 4px; font-size: 1rem; }
#chosenSeats { margin: 0; color: #60736d; }
.price { display: grid; justify-items: end; gap: 2px; color: #60736d; }
.price strong { color: #18332e; font-size: 1.45rem; }
.status { min-height: 1.4em; margin: 14px 2px 4px; color: #a34c36; font-size: .9rem; }
.note { margin: 0; color: #71827c; font-size: .85rem; text-align: center; }
@media (max-width: 400px) { body { padding: 16px 10px; } .booking-card { padding: 22px 16px; } .bus { padding: 16px 12px 14px; } .seat-map { gap: 8px 5px; } .seat { min-height: 40px; font-size: .9rem; } .aisle { font-size: .58rem; } }

const seatMap = document.querySelector('#seatMap');
const chosenSeats = document.querySelector('#chosenSeats');
const totalPrice = document.querySelector('#totalPrice');
const status = document.querySelector('#status');
const booked = new Set(['1B', '3D', '5A', '7C', '9B']);
const selected = new Set();

for (let row = 1; row <= 10; row++) {
  if (row === 1) {
    const aisle = document.createElement('span');
    aisle.className = 'aisle';
    aisle.textContent = 'AISLE';
    aisle.setAttribute('aria-hidden', 'true');
    seatMap.append(aisle);
  }
  for (const letter of ['A', 'B', 'C', 'D']) {
    const code = `${row}${letter}`;
    const button = document.createElement('button');
    button.type = 'button';
    button.className = `seat${booked.has(code) ? ' booked' : ''}`;
    button.textContent = code;
    button.setAttribute('aria-label', `${code}, ${booked.has(code) ? 'booked' : 'available'}`);
    if (booked.has(code)) button.disabled = true;
    button.addEventListener('click', () => toggleSeat(code, button));
    seatMap.append(button);
  }
}

function toggleSeat(code, button) {
  status.textContent = '';
  if (selected.has(code)) {
    selected.delete(code);
    button.classList.remove('selected');
    button.setAttribute('aria-label', `${code}, available`);
    button.setAttribute('aria-pressed', 'false');
  } else if (selected.size === 4) {
    status.textContent = 'You can choose up to 4 seats.';
    return;
  } else {
    selected.add(code);
    button.classList.add('selected');
    button.setAttribute('aria-label', `${code}, selected`);
    button.setAttribute('aria-pressed', 'true');
  }
  const seats = [...selected].sort((a, b) => Number(a.slice(0, -1)) - Number(b.slice(0, -1)) || a.localeCompare(b));
  chosenSeats.textContent = seats.length ? seats.join(', ') : 'None selected';
  const subtotal = seats.length * 12;
  const total = seats.length === 4 ? subtotal * 0.9 : subtotal;
  totalPrice.textContent = `$${Number.isInteger(total) ? total : total.toFixed(2)}`;
  if (seats.length === 4) status.textContent = '10% discount applied.';
}
